//==============================================================================
// 文件名: harness.sv
// 描述:   测试平台顶层模块
//         例化 interface、产生 clk/rst、设置 virtual interface、启动 run_test
//==============================================================================

`timescale 1ns/1ps

module harness;

    // 导入 UVM 库和 Agent 包
    import uvm_pkg::*;
    import uart_package::*;

    //==========================================================================
    // 时钟和复位信号
    //==========================================================================
    
    logic clk;
    logic rst_n;

    //==========================================================================
    // 接口例化
    //==========================================================================
    
    uart_interface uart_if (
        .clk   (clk),
        .rst_n (rst_n)
    );

    //==========================================================================
    // 时钟生成 (100MHz)
    //==========================================================================
    
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    //==========================================================================
    // 复位生成
    //==========================================================================
    
    initial begin
        rst_n = 0;
        repeat (10) @(posedge clk);
        rst_n = 1;
    end

    //==========================================================================
    // UVM 配置和启动
    //==========================================================================
    
    initial begin
        // 设置虚拟接口
        uvm_config_db#(virtual uart_interface)::set(null, "*", "vif", uart_if);
        
        // 启动 UVM 测试
        run_test();
    end

    //==========================================================================
    // 波形转储 (可选)
    //==========================================================================
    
    initial begin
        if ($test$plusargs("dump_wave")) begin
            $fsdbDumpfile("wave.fsdb");
            $fsdbDumpvars(0, harness);
        end
    end

endmodule
